/**
 * Every texture the game loads. Sprite sheets are paired with the atlas JSON
 * generated by `npm run atlas` (tools/slice-sprites.ps1 + tools/sheets.json).
 */
import playerPng from '../../assets/SpaceShips_Player-0001.png';
import enemyPng from '../../assets/SpaceShips_Enemy-0001.png';
import bossPng from '../../assets/SpaceShip_Boss-0001.png';
import bulletsPng from '../../assets/Bullets-0001.png';
import bonusesPng from '../../assets/Bonuses-0001.png';
import explosionPng from '../../assets/Explosion-0001.png';
import exhaustPng from '../../assets/Exhaust-0001.png';
import minePng from '../../assets/Mine-0001.png';
import asteroidsPng from '../../assets/Asteroids-0001.png';
import barrierPng from '../../assets/Barrier-0001.png';
import uiPng from '../../assets/UI_sprites-0001.png';

import playerAtlas from './atlases/player.json';
import enemyAtlas from './atlases/enemy.json';
import bossAtlas from './atlases/boss.json';
import bulletsAtlas from './atlases/bullets.json';
import bonusesAtlas from './atlases/bonuses.json';
import explosionAtlas from './atlases/explosion.json';
import exhaustAtlas from './atlases/exhaust.json';
import mineAtlas from './atlases/mine.json';
import asteroidsAtlas from './atlases/asteroids.json';
import barrierAtlas from './atlases/barrier.json';
import uiAtlas from './atlases/ui.json';

import bgSpace from '../../assets/Background_Space-0001.png';
import bgNebula1 from '../../assets/Background_Nebula-0001.png';
import bgNebula2 from '../../assets/Background_Nebula-0002.png';
import bgSmallStars from '../../assets/Background_SmallStars-0001.png';
import bgStars from '../../assets/Background_Stars-0001.png';
import bgFull from '../../assets/Background_Full-0001.png';

export const ATLASES = [
  { key: 'player', image: playerPng, data: playerAtlas },
  { key: 'enemy', image: enemyPng, data: enemyAtlas },
  { key: 'boss', image: bossPng, data: bossAtlas },
  { key: 'bullets', image: bulletsPng, data: bulletsAtlas },
  { key: 'bonuses', image: bonusesPng, data: bonusesAtlas },
  { key: 'explosion', image: explosionPng, data: explosionAtlas },
  { key: 'exhaust', image: exhaustPng, data: exhaustAtlas },
  { key: 'mine', image: minePng, data: mineAtlas },
  { key: 'asteroids', image: asteroidsPng, data: asteroidsAtlas },
  { key: 'barrier', image: barrierPng, data: barrierAtlas },
  { key: 'ui', image: uiPng, data: uiAtlas },
] as const;

export type AtlasKey = (typeof ATLASES)[number]['key'];

/** Background layers, back to front. 320x320 seamless tiles. */
export const BACKGROUNDS = [
  { key: 'bg_space', url: bgSpace },
  { key: 'bg_nebula_1', url: bgNebula1 },
  { key: 'bg_nebula_2', url: bgNebula2 },
  { key: 'bg_small_stars', url: bgSmallStars },
  { key: 'bg_stars', url: bgStars },
  { key: 'bg_full', url: bgFull },
] as const;

export type BackgroundKey = (typeof BACKGROUNDS)[number]['key'];
